const tripStartFacts = `-- name: TripStartFacts :one
SELECT a.state AS asset_state,a.kind AS asset_kind,a.disposed_at,a.disposed_submicro,
 EXISTS(SELECT 1 FROM org_employee_identities e WHERE e.org_id=a.org_id AND e.id=CAST($1::text AS uuid) AND e.state='ACTIVE' AND e.merged_into IS NULL)::boolean AS driver_active,
 COALESCE((SELECT t.operation_id::text FROM org_trips t WHERE t.org_id=a.org_id AND t.id=CAST($2::text AS uuid)),'')::text AS existing_operation,
 COALESCE((SELECT h.operation_id::text FROM org_trip_held_starts h WHERE h.org_id=a.org_id AND h.trip_id=CAST($2::text AS uuid)),'')::text AS held_operation,
 COALESCE((SELECT t.id::text FROM org_trips t WHERE t.org_id=a.org_id AND t.asset_id=a.id AND t.state IN('IN_PROGRESS','PAUSED')),'')::text AS active_trip,
 COALESCE(o.time_zone,'')::text AS organization_zone
FROM org_assets a JOIN organizations o ON o.org_id=a.org_id
WHERE a.org_id=CAST($3::text AS uuid) AND a.id=CAST($4::text AS uuid)
`

type TripStartFactsParams struct {
	DriverID string `json:"driver_id"`
	TripID   string `json:"trip_id"`
	OrgID    string `json:"org_id"`
	AssetID  string `json:"asset_id"`
}

type TripStartFactsRow struct {
	AssetState        string             `json:"asset_state"`
	AssetKind         string             `json:"asset_kind"`
	DisposedAt        pgtype.Timestamptz `json:"disposed_at"`
	DisposedSubmicro  int16              `json:"disposed_submicro"`
	DriverActive      bool               `json:"driver_active"`
	ExistingOperation string             `json:"existing_operation"`
	HeldOperation     string             `json:"held_operation"`
	ActiveTrip        string             `json:"active_trip"`
	OrganizationZone  string             `json:"organization_zone"`
}

// Admission facts of one start, taken after the root and asset locks.
func (q *Queries) TripStartFacts(ctx context.Context, arg TripStartFactsParams) (TripStartFactsRow, error) {
	row := q.db.QueryRow(ctx, tripStartFacts,
		arg.DriverID,
		arg.TripID,
		arg.OrgID,
		arg.AssetID,
	)
	var i TripStartFactsRow
	err := row.Scan(
		&i.AssetState,
		&i.AssetKind,
		&i.DisposedAt,
		&i.DisposedSubmicro,
		&i.DriverActive,
		&i.ExistingOperation,
		&i.HeldOperation,
		&i.ActiveTrip,
		&i.OrganizationZone,
	)
	return i, err
}

